    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">F = x - 2</span> حيث <span dir=\"ltr\" class=\"expr\">F = x - [3 - (4 - x)] - [-1 - (x - 4)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">F = x - 2</span> حيث احسب <span dir=\"ltr\" class=\"expr\">F</span> في حالة <span dir=\"ltr\" class=\"expr\">x = -1</span> <span dir=\"ltr\" class=\"expr\">F = x - [3 - (4 - x)] - [-1 - (x - 4)]</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">F = x - 2</span> حيث احسب <span dir=\"ltr\" class=\"expr\">F</span> في حالة <span dir=\"ltr\" class=\"expr\">x = -1</span> أوجد <span dir=\"ltr\" class=\"expr\">x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">F = -11</span> و <span dir=\"ltr\" class=\"expr\">F = x - 2</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوسين الداخليين","math":"<span dir=\"ltr\" class=\"expr\">(4 - x)</span> و <span dir=\"ltr\" class=\"expr\">(x - 4)</span> متقابلان"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [3 - 4 + x] = -3 + 4 - x</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [-1 - x + 4] = 1 + x - 4</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = x - 3 + 4 - x + 1 + x - 4</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (x - x + x) + (-3 + 4 + 1 - 4)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-3 + 4 + 1 - 4 = -2</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 2</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">x = -1</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">F = (-1) - 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = -3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = x - 2</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(x) - 2 = -11</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">x = (-11) - (-2)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -9</span>"}],
