    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">+ (-b + 9) = -b + 9</span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (-a + 3) = a - 3</span>"},{"quoi":"نرفع القوس الثالث","math":"<span dir=\"ltr\" class=\"expr\">- (-4 + c - 1) = 4 - c + 1</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">N = -6 - b + 9 + a - 3 + 4 - c + 1</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + (-6 + 9 - 3 + 4 + 1)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-6 + 9 - 3 + 4 + 1 = 5</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">N = a - b - c + 5</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">N = 7 - 1 - 5 + 5</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">7 - 1 - 5 + 5 = 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 6</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">-5 + -1 - |x| = 0</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-5 + (-1) = -6</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-6 - |x| = 0</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-6) - 0</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-6) - 0 = -6</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-6 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"}],
