    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">P = b - a - 5</span> حيث <span dir=\"ltr\" class=\"expr\">P = -1 + [-a - 19 - (-15 - b)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">P = b - a - 5</span> حيث <span dir=\"ltr\" class=\"expr\">Q = a + b - 7</span> <span dir=\"ltr\" class=\"expr\">Q = (-4 + a) - [1 + (2 - b)]</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">P = b - a - 5</span> حيث <span dir=\"ltr\" class=\"expr\">Q = a + b - 7</span> ليكن a و b أعدادا كسرية نسبية حيث <span dir=\"ltr\" class=\"expr\">b - a = 7</span> ؛ قارن بين P  و  8<br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">P = b - a - 5</span> حيث <span dir=\"ltr\" class=\"expr\">Q = a + b - 7</span> ليكن a و b أعدادا كسرية نسبية حيث <span dir=\"ltr\" class=\"expr\">b - a = 7</span> ؛ قارن بين قارن Q و 8 إذا كان a و b متقابلان <span dir=\"ltr\" class=\"expr\">Q = a + b - 7</span><br><span class=\"q\">5) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">P = b - a - 5</span> حيث <span dir=\"ltr\" class=\"expr\">Q = a + b - 7</span> ليكن a و b أعدادا كسرية نسبية حيث <span dir=\"ltr\" class=\"expr\">b - a = 7</span> ؛ قارن بين قارن Q و 8 إذا كان a و b متقابلان احسب <span dir=\"ltr\" class=\"expr\">P</span> في حالة <span dir=\"ltr\" class=\"expr\">b = -8</span> و <span dir=\"ltr\" class=\"expr\">a = -4</span> <span dir=\"ltr\" class=\"expr\">P = -1 + [-a - 19 - (-15 - b)]</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">- (-15 - b) = 15 + b</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">+ [-a - 19 + 15 + b] = -a - 19 + 15 + b</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">P = -1 - a - 19 + 15 + b</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">P = b - a + (-1 - 19 + 15)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 - 19 + 15 = -5</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">P = b - a - 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">1 + (2 - b) = 1 + 2 - b</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [1 + 2 - b] = -1 - 2 + b</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">Q = -4 + a - 1 - 2 + b</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">Q = a + b + (-4 - 1 - 2)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 - 1 - 2 = -7</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">Q = a + b - 7</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(P) - (8) = (b - a) - 13</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">(b - a) - 13 = 7 - 13</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">7 - 13 = -6</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-6 &lt; 0</span>"},{"quoi":"القاعدة","math":"الفرق سالب، إذن العبارة الأولى أصغر"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P &lt; 8</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم « متقابلان »","math":"<span dir=\"ltr\" class=\"expr\">a + b = 0</span>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">Q = (a + b) - 7</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">Q = 0 - 7</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">Q - 8 = -15</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-15 &lt; 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">Q &lt; 8</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">P = b - a - 5</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">b = -8</span> و <span dir=\"ltr\" class=\"expr\">a = -4</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">P = (-8) - (-4) - 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = -9</span>"}],
