    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 11</span> حيث <span dir=\"ltr\" class=\"expr\">G = -[-2 - (1 - a)] - [(b - 9) + (1 - a)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 11</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">b</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">G = -15</span> و <span dir=\"ltr\" class=\"expr\">G = -b + 11</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 11</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">b</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">G = -15</span> و احسب <span dir=\"ltr\" class=\"expr\">b + |-G| + 5</span> إذا كان <span dir=\"ltr\" class=\"expr\">b = -3</span> <span dir=\"ltr\" class=\"expr\">G = -b + 11</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نلاحظ المجموعة المتكرّرة","math":"<span dir=\"ltr\" class=\"expr\">(1 - a)</span> موجودة مرّتين بإشارتين متعاكستين"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">-[-2 - (1 - a)] = 2 + 1 - a</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(b - 9) + (1 - a)] = -b + 9 - 1 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">G = 2 + 1 - a - b + 9 - 1 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">G = (-a + a) + (1 - 1) - b + (2 + 9)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">2 + 1 + 9 - 1 = 11</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 11</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 11</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) + 11 = -15</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = (-15) - 11</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = -26</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب G","math":"<span dir=\"ltr\" class=\"expr\">G = -(-3) + 11 = 14</span>"},{"quoi":"القاعدة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = |G|</span> لأنّ العددين المتقابلين لهما نفس القيمة المطلقة"},{"quoi":"نحسب القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = 14</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">b + |-G| + 5 = (-3) + 14 + 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">(-3) + 14 + 5 = 16</span>"}],
