    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 16</span> حيث <span dir=\"ltr\" class=\"expr\">G = -[-8 - (9 - a)] - [(b - 8) + (9 - a)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 16</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">b</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">G = -6</span> و <span dir=\"ltr\" class=\"expr\">G = -b + 16</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">G = -b + 16</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">b</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">G = -6</span> و احسب <span dir=\"ltr\" class=\"expr\">b + |-G| + 8</span> إذا كان <span dir=\"ltr\" class=\"expr\">b = -3</span> <span dir=\"ltr\" class=\"expr\">G = -b + 16</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نلاحظ المجموعة المتكرّرة","math":"<span dir=\"ltr\" class=\"expr\">(9 - a)</span> موجودة مرّتين بإشارتين متعاكستين"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">-[-8 - (9 - a)] = 8 + 9 - a</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(b - 8) + (9 - a)] = -b + 8 - 9 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">G = 8 + 9 - a - b + 8 - 9 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">G = (-a + a) + (9 - 9) - b + (8 + 8)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">8 + 9 + 8 - 9 = 16</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 16</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">G = -b + 16</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) + 16 = -6</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = (-6) - 16</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = -22</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب G","math":"<span dir=\"ltr\" class=\"expr\">G = -(-3) + 16 = 19</span>"},{"quoi":"القاعدة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = |G|</span> لأنّ العددين المتقابلين لهما نفس القيمة المطلقة"},{"quoi":"نحسب القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-G| = 19</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">b + |-G| + 8 = (-3) + 19 + 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">(-3) + 19 + 8 = 24</span>"}],
