    enonce: "<span class=\"q\">1) </span>احسب <span dir=\"ltr\" class=\"expr\">A</span> إذا كان <span dir=\"ltr\" class=\"expr\">a = 9</span> حيث <span dir=\"ltr\" class=\"expr\">A = -4 - |a + 2| + |a - 3| + |a| - (-2)</span><br><span class=\"q\">2) </span>احسب <span dir=\"ltr\" class=\"expr\">A</span> إذا كان <span dir=\"ltr\" class=\"expr\">a = 9</span> حيث بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = y + z + 8</span> <span dir=\"ltr\" class=\"expr\">B = -2 - [x - (z + y)] - [(-x + y - 4) + (-6 - y)]</span><br><span class=\"q\">3) </span>احسب <span dir=\"ltr\" class=\"expr\">A</span> إذا كان <span dir=\"ltr\" class=\"expr\">a = 9</span> حيث بيّن أنّ: <span dir=\"ltr\" class=\"expr\">B = y + z + 8</span> <span dir=\"ltr\" class=\"expr\">B</span> في حالة <span dir=\"ltr\" class=\"expr\">y = 6</span> و <span dir=\"ltr\" class=\"expr\">z = 2</span> <span dir=\"ltr\" class=\"expr\">B = -2 - [x - (z + y)] - [(-x + y - 4) + (-6 - y)]</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = -4 - |9 + 2| + |9 - 3| + |9| + 2</span>"},{"quoi":"القيمة المطلقة الأولى","math":"<span dir=\"ltr\" class=\"expr\">|9 + 2| = 11</span>"},{"quoi":"القيمة المطلقة الثانية","math":"<span dir=\"ltr\" class=\"expr\">|9 - 3| = 6</span>"},{"quoi":"القيمة المطلقة الثالثة","math":"<span dir=\"ltr\" class=\"expr\">|9| = 9</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">A = -4 - 11 + 6 + 9 + 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المربّع الأول","math":"<span dir=\"ltr\" class=\"expr\">- [x - (z + y)] = -x + z + y</span>"},{"quoi":"نرفع القوس المربّع الثاني","math":"<span dir=\"ltr\" class=\"expr\">- [(-x + y - 4) + (-6 - y)] = x - y + 4 + 6 + y</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = -2 - x + z + y + x - y + 4 + 6 + y</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = (-x + x) + (y - y + y) + z + (-2 + 4 + 6)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + 4 + 6 = 8</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 8</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = y + z + 8</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = 6</span> و <span dir=\"ltr\" class=\"expr\">z = 2</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">B = 6 + 2 + 8</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">B = 16</span>"}],
