    enonce: "<span class=\"q\">1) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">7 - (-5 - x) = 9</span><br><span class=\"q\">2) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">6 + (x - (-6)) = -7</span><br><span class=\"q\">3) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">1 - (x + 5) = -3</span><br><span class=\"q\">4) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">7 + [-8 - x] = -5</span><br><span class=\"q\">5) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-6 - |x| = 0</span><br><span class=\"q\">6) </span>جد العدد الصحيح النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">-8 + |x| = 6</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">7 - (-5) + x = 9</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">7 - (-5) = 12</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">12 + x = 9</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 9 - 12</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">9 - 12 = -3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -3</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">7 - (-5 - (-3)) = 9</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بالجمع","math":"<span dir=\"ltr\" class=\"expr\">6 + x - (-6) = -7</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">6 - (-6) = 12</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">12 + x = -7</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-7) - 12</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-7) - 12 = -19</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -19</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">6 + ((-19) - (-6)) = -7</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نرفع القوس المسبوق بالطرح","math":"<span dir=\"ltr\" class=\"expr\">1 - x - 5 = -3</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">1 - 5 = -4</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-4 - x = -3</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-4) - (-3)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-4) - (-3) = -1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -1</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">1 - ((-1) + 5) = -3</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">7 + -8 - x = -5</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">7 + (-8) = -1</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-1 - x = -5</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = (-1) - (-5)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-1) - (-5) = 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 4</span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">7 + [-8 - 4] = -5</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = (-6) - 0</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">(-6) - 0 = -6</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-6 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد صحيح نسبي x يحقّق المعادلة"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">|x| = 6 - (-8)</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">6 - (-8) = 14</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">14 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 14</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -14</span>"}],
